package com.vitaltrace.app.feature.nurseportal.data.dto

import com.vitaltrace.app.feature.patient.data.dto.appointments.SpecialtyDto
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

@Serializable data class NurseSummaryDto(val nurse: NurseInfoDto, @SerialName("assigned_patients_count") val assignedPatientsCount: Int, val alerts: NurseAlertsSummaryDto, val appointments: NurseAppointmentsSummaryDto)
@Serializable data class NurseInfoDto(val id: Long, @SerialName("full_name") val fullName: String, @SerialName("professional_code") val professionalCode: String, val specialty: String? = null)
@Serializable data class NurseAlertsSummaryDto(@SerialName("total_pending") val totalPending: Int, val new: Int, val critical: Int)
@Serializable data class NurseAppointmentsSummaryDto(@SerialName("upcoming_count") val upcomingCount: Int, val next: List<NurseAppointmentDto> = emptyList())
@Serializable data class NursePatientDto(@SerialName("patient_id") val patientId: Long, @SerialName("record_number") val recordNumber: String, @SerialName("full_name") val fullName: String, @SerialName("birth_date") val birthDate: String? = null, val age: Int? = null, val sex: String? = null, @SerialName("administrative_status") val administrativeStatus: String, @SerialName("active_alerts_count") val activeAlertsCount: Int = 0, @SerialName("critical_alerts_count") val criticalAlertsCount: Int = 0, @SerialName("last_measurement") val lastMeasurement: NurseMeasurementDto? = null, @SerialName("next_appointment") val nextAppointment: NurseAppointmentDto? = null)
@Serializable data class NursePatientProfileDto(val id: Long, @SerialName("full_name") val fullName: String, @SerialName("record_number") val recordNumber: String, val sex: String? = null, @SerialName("birth_date") val birthDate: String? = null, val age: Int? = null, val phone: String? = null, @SerialName("emergency_contact") val emergencyContact: NurseEmergencyContactDto? = null, val status: String)
@Serializable data class NurseEmergencyContactDto(val name: String? = null, val phone: String? = null)
@Serializable data class NursePatientSummaryDto(val patient: NursePatientDto, @SerialName("recent_measurements") val recentMeasurements: List<NurseMeasurementDto> = emptyList(), val diagnoses: List<NurseDiagnosisDto> = emptyList(), @SerialName("active_treatments") val activeTreatments: List<NurseTreatmentDto> = emptyList(), @SerialName("upcoming_appointment") val upcomingAppointment: NurseAppointmentDto? = null, @SerialName("active_alerts") val activeAlerts: List<NurseAlertDto> = emptyList())
@Serializable data class NurseAppointmentDto(val id: Long, @SerialName("patient_id") val patientId: Long, @SerialName("scheduled_at") val scheduledAt: String, @SerialName("duration_minutes") val durationMinutes: Int, val reason: String, val status: String, val professional: NurseProfessionalDto? = null)
@Serializable data class NurseProfessionalDto(val id: Long, @SerialName("full_name") val fullName: String? = null, @SerialName("professional_type") val professionalType: String? = null, val specialty: SpecialtyDto? = null)
@Serializable data class NurseMeasurementDto(val id: Long, @SerialName("patient_id") val patientId: Long, @SerialName("measurement_type") val measurementType: NurseMeasurementTypeRefDto? = null, val value: String, val unit: String, @SerialName("measured_at") val measuredAt: String, val origin: String, val observation: String? = null, @SerialName("review_status") val reviewStatus: String? = null)
@Serializable data class NurseMeasurementTypeRefDto(val id: Long, val name: String, @SerialName("base_unit") val baseUnit: String, val decimals: Int)
@Serializable data class NurseMeasurementTypeDto(val id: Long, val name: String, val unit: String, val decimals: Int, val active: Boolean)
@Serializable data class NurseMeasurementRequestDto(@SerialName("measurement_type_id") val measurementTypeId: Long, val value: Double, val unit: String, @SerialName("measured_at") val measuredAt: String, val observation: String? = null)
@Serializable data class NurseDiagnosisDto(val id: Long, @SerialName("cie_code") val cieCode: String? = null, val description: String, @SerialName("diagnosis_date") val diagnosisDate: String, val status: String)
@Serializable data class NurseTreatmentDto(val id: Long, @SerialName("patient_id") val patientId: Long, val indication: String, @SerialName("start_date") val startDate: String, @SerialName("end_date") val endDate: String? = null, val status: String, val diagnosis: NurseDiagnosisDto? = null, val medications: List<NurseMedicationDto> = emptyList())
@Serializable data class NurseMedicationDto(val id: Long? = null, val name: String? = null, val dose: String? = null, val route: String? = null, val frequency: String? = null, val schedules: String? = null, @SerialName("start_date") val startDate: String? = null, @SerialName("end_date") val endDate: String? = null)
@Serializable data class NurseClinicalHistoryDto(val patient: NursePatientDto, val diagnoses: List<NurseDiagnosisDto> = emptyList(), val evolutions: List<NurseClinicalEvolutionDto> = emptyList(), val treatments: List<NurseTreatmentDto> = emptyList(), val measurements: List<NurseMeasurementDto> = emptyList())
@Serializable data class NurseClinicalEvolutionDto(val id: Long, @SerialName("clinical_summary") val clinicalSummary: String, val status: String, @SerialName("recorded_at") val recordedAt: String)
@Serializable data class NurseAlertDto(val id: Long, @SerialName("patient_id") val patientId: Long, @SerialName("measurement_id") val measurementId: Long? = null, val type: String, val severity: String, val status: String, val description: String, @SerialName("generated_at") val generatedAt: String, @SerialName("closed_at") val closedAt: String? = null, val history: List<NurseAlertHistoryDto> = emptyList())
@Serializable data class NurseAlertHistoryDto(val id: Long, val action: String, @SerialName("previous_status") val previousStatus: String? = null, @SerialName("new_status") val newStatus: String? = null, val comment: String? = null, @SerialName("created_at") val createdAt: String? = null)
@Serializable data class NurseAlertActionDto(val comment: String? = null)